def solve():
    import sys
    data = sys.stdin.read().split()
    idx = 0
    r = int(data[idx]); c = int(data[idx + 1]); idx += 2
    grid = []
    for _ in range(r):
        row = list(map(int, data[idx:idx + c]))
        idx += c
        grid.append(row)

    dp = [[0] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j - 1] + grid[i][j]
            elif j == 0:
                dp[i][j] = dp[i - 1][j] + grid[i][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

    print(dp[r - 1][c - 1])


solve()
